                        b[i + j] = uB + vB;
                        a[i + j + halfLen] = uA - vA;
                        b[i + j + halfLen] = uB - vB;
                    }
                }
                lvl++;
            }
            if (inverse) {
                for (int i = 0; i < n; i++) {
                    a[i] /= n;
