    int nextInt() {
        int c = read();
        while (isWhitespace(c))
            c = read();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw runtime_error("InputMismatchException");
            res = res * 10 + c - '0';
            c = read();
        } while (!isWhitespace(c));
        return res * sign;
    }

private:
    char buf[1024];
    int pos;
    int size;

    int read() {
        if (pos >= size) {
            pos = 0;
            size = fread(buf, 1, 1024, stdin);
            if (size <= 0)
